1	import java.util.HashMap;
2	import java.util.Map;
3	
4	/**
5	 * This class collects and provides some statistical data on the state
6	 * of a field. It is flexible: it will create and maintain a counter
7	 * for any class of object that is found within the field.
8	 *
9	 * @version 2016.02.29
10	 */
11	public class FieldStats
12	{
13	    // Counts per species class; populated on demand.
14	    private HashMap<Class<?>, Integer> counts;
15	    // Whether the counts are currently up to date.
16	    private boolean countsValid;
17	
18	    /**
19	     * Construct a FieldStats object.
20	     */
21	    public FieldStats()
22	    {
23	        counts      = new HashMap<>();
24	        countsValid = true;
25	    }
26	
27	    /**
28	     * Get details of what is in the field.
29	     * @return A string describing what is in the field.
30	     */
31	    public String getPopulationDetails(Field field)
32	    {
33	        StringBuilder buffer = new StringBuilder();
34	        if (!countsValid) {
35	            generateCounts(field);
36	        }
37	        for (Map.Entry<Class<?>, Integer> entry : counts.entrySet()) {
38	            buffer.append(entry.getKey().getSimpleName());
39	            buffer.append(": ");
40	            buffer.append(entry.getValue());
41	            buffer.append(' ');
42	        }
43	        return buffer.toString();
44	    }
45	
46	    /**
47	     * Invalidate the current set of statistics; reset all counts to zero.
48	     */
49	    public void reset()
50	    {
51	        countsValid = false;
52	        counts.replaceAll((k, v) -> 0);
53	    }
54	
55	    /**
56	     * Increment the count for one class of organism.
57	     * @param speciesClass The class of organism to increment.
58	     */
59	    public void incrementCount(Class<?> speciesClass)
60	    {
61	        counts.merge(speciesClass, 1, Integer::sum);
62	    }
63	
64	    /**
65	     * Indicate that a count has been completed.
66	     */
67	    public void countFinished()
68	    {
69	        countsValid = true;
70	    }
71	
72	    /**
73	     * Determine whether the simulation is still viable (more than one species alive).
74	     * @return true if there is more than one species alive.
75	     */
76	    public boolean isViable(Field field)
77	    {
78	        if (!countsValid) {
79	            generateCounts(field);
80	        }
81	        int nonZero = 0;
82	        for (int count : counts.values()) {
83	            if (count > 0) nonZero++;
84	        }
85	        return nonZero > 1;
86	    }
87	
88	    /**
89	     * Generate counts of all species currently in the field.
90	     * @param field The field to generate the stats for.
91	     */
92	    private void generateCounts(Field field)
93	    {
94	        reset();
95	        for (int row = 0; row < field.getDepth(); row++) {
96	            for (int col = 0; col < field.getWidth(); col++) {
97	                Organism organism = field.getObjectAt(row, col);
98	                if (organism != null) {
99	                    incrementCount(organism.getClass());
100	                }
101	            }
102	        }
103	        countsValid = true;
104	    }
105	}
